import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate, useLocation } from 'react-router-dom';
import Header from './components/UsersPages/Header';
import Login from './components/UsersPages/Auth/Login';
import Register from './components/UsersPages/Auth/Register';
import Home from './components/UsersPages/Home';
import Dashboard from './components/UsersPages/DashboardLayout';
import ProtectedRoute from './components/UsersPages/Auth/ProtectedRoute';

const AppWrapper = () => {
  return (
    <Router>
      <App />
    </Router>
  );
};

const App = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const location = useLocation();

  useEffect(() => {
    const checkAuth = () => {
      const userEmail = localStorage.getItem('userEmail');
      const token = localStorage.getItem('authToken');

      if (userEmail || token) {
        setIsAuthenticated(true);
      }
      setIsLoading(false);
    };

    checkAuth();
  }, []);

  const handleLogin = (userData) => {
    localStorage.setItem('authToken', 'demo-token-12345');
    localStorage.setItem('userEmail', userData.email);
    setIsAuthenticated(true);
  };

  const handleLogout = () => {
    localStorage.removeItem('authToken');
    localStorage.removeItem('userEmail');
    localStorage.removeItem('rememberMe');
    setIsAuthenticated(false);
  };

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-white dark:bg-neutral-950">
        <div className="text-center">
          <div className="h-12 w-12 border-4 border-primary-500 border-t-transparent rounded-full animate-spin mx-auto"></div>
          <p className="mt-4 text-neutral-600 dark:text-neutral-400">Chargement...</p>
        </div>
      </div>
    );
  }

  const showHeader = !(
    location.pathname.startsWith('/dashboard') ||
    location.pathname === '/login' ||
    location.pathname === '/register'
  );

  return (
    <>
      {showHeader && <Header isAuthenticated={isAuthenticated} onLogout={handleLogout} />}
      <div className="min-h-screen bg-white dark:bg-neutral-950 text-neutral-900 dark:text-white">
        <Routes>
          <Route path="/" element={
            <div className="container mx-auto px-4 py-8">
              <Home />
            </div>
          } />

          <Route path="/login" element={
            isAuthenticated ? 
            <Navigate to="/dashboard" replace /> : 
            <Login onLogin={handleLogin} />
          } />

          <Route path="/register" element={
            isAuthenticated ? 
            <Navigate to="/dashboard" replace /> : 
            <Register />
          } />

          <Route path="/dashboard/*" element={
            <ProtectedRoute isAuthenticated={isAuthenticated}>
              <Dashboard onLogout={handleLogout} />
            </ProtectedRoute>
          } />

          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </div>
    </>
  );
};

export default AppWrapper;
